export class LaneController {
  flags: boolean[] = [false, false, false];
  onClick(index: number): void {
    this.flags[index] = !this.flags[index];
    if (index + 1 < this.flags.length) {
      this.flags[index + 1] = this.flags[index];
    }
  }
}

